  var rightOpacity = state.annotate && !state.focusCritical ? 0.34 : 1;

  var left = root.group().opacity(leftOpacity);
  var right = root.group().opacity(rightOpacity);
  drawLeftPanel(left, 1);
  drawRightPanel(right, 1);

  textWithHalo(root, '(a)', 207, 506, 25, 'normal', 'middle');
  textWithHalo(root, '(b)', 707, 506, 25, 'normal', 'middle');

  if (state.annotate) {
    var m = state.mass;
    var x0 = 405, y0 = 513, w = 165;
    root.line(x0, y0, x0 + w, y0).stroke({ color: '#777', width: 3, linecap: 'round' });
    var tx = x0 + w * ((1.0 - 0.4) / 0.8);
    root.line(tx, y0 - 8, tx, y0 + 8).stroke({ color: '#c33', width: 2 });
    textWithHalo(root, 'critical mass', tx, y0 - 31, 13, 'bold', 'middle').fill('#b22');
    var px = x0 + w * ((m - 0.4) / 0.8);
    root.circle(12).center(px, y0).fill(m >= 1 ? '#2ca25f' : '#e6a23c').stroke({ color: '#222', width: 1 });
  }
}

function stopAnimation() {
  animTimers.forEach(function (t) { clearTimeout(t); });
  animTimers = [];
  state.animating = false;
  state.generation = -1;
}

function toggle_massView(on) {
  stopAnimation();
  state.focusCritical = !!on;
  state.annotate = true;
  redraw();
}

function update_fissileMass(v) {
  stopAnimation();
  state.mass = v;
  state.annotate = true;
  if (v >= 1) {
    state.focusCritical = true;
    document.getElementById('massViewInput').checked = true;
  }
  redraw();
}

function trigger_chainReaction() {
  stopAnimation();
  state.focusCritical = true;
  state.mass = Math.max(state.mass, 1);
  state.annotate = true;
  state.animating = true;
  state.generation = -1;
  document.getElementById('massViewInput').checked = true;
  document.getElementById('fissileMassInput').value = state.mass.toFixed(2);
  document.getElementById('fissileMassVal').value = state.mass.toFixed(2);
  redraw();
  [0, 1, 2, 3].forEach(function (gen, i) {
    animTimers.push(setTimeout(function () {
      state.generation = gen;
      state.animating = true;
      redraw();
    }, 450 + i * 650));
  });
  animTimers.push(setTimeout(function () {
    state.animating = false;
    state.generation = -1;
    redraw();
  }, 3500));
}

var steps = [
  {
    narration: 'In the sub-critical sample, the circle is small and most neutron arrows leave the material before hitting another nucleus. The chain reaction dies out because neutron escape exceeds productive neutron capture.',
    massView: false,
    mass: 0.6,
    animate: false
  },
  {
    narration: 'Move the mass slider upward: the blue sample grows, and fewer neutron paths reach the boundary before another fission site. The decreasing escape fraction is the geometric reason a larger sample can sustain a reaction.',
    massView: false,
    mass: 0.9,
    animate: false
  },
  {
    narration: 'At the critical threshold, neutron production balances neutron loss by escape and absorption. The diagram now emphasizes many internal neutron paths that connect one fission event to the next.',
    massView: true,
    mass: 1.0,
    animate: false
  },
  {
    narration: 'Play the cascade animation in the critical mass: one incoming neutron triggers fission, then the next generations spread as 2, 4, and 8 events. This shows how retained neutrons make the reaction self-sustaining.',
    massView: true,
    mass: 1.0,
    animate: true
  }
];

var currentStep = 0;

function applyStep(i) {
  currentStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[currentStep];
  stopAnimation();
  state.focusCritical = s.massView;
  state.mass = s.mass;
  state.annotate = currentStep !== 0;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + ' / ' + steps.length;
  document.getElementById('massViewInput').checked = state.focusCritical;
  document.getElementById('fissileMassInput').value = state.mass.toFixed(2);
  document.getElementById('fissileMassVal').value = state.mass.toFixed(2);
  if (s.animate) trigger_chainReaction();
  else redraw();
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

applyStep(0);
